import numpy as np
import pandas as pd
import random
def task_func(rows=3, cols=2, min_val=0, max_val=100, seed=0):
    if not isinstance(rows, (int, np.integer)) or isinstance(rows, bool):
        raise TypeError("rows must be a non-negative integer")
    if not isinstance(cols, (int, np.integer)) or isinstance(cols, bool):
        raise TypeError("cols must be a non-negative integer")
    if rows < 0 or cols < 0:
        raise ValueError("rows and cols must be non-negative")
    if not isinstance(min_val, (int, np.integer)) or isinstance(min_val, bool):
        raise TypeError("min_val must be an integer")
    if not isinstance(max_val, (int, np.integer)) or isinstance(max_val, bool):
        raise TypeError("max_val must be an integer")
    if min_val > max_val:
        raise ValueError("min_val must be less than or equal to max_val")

    random.seed(seed)
    rng = np.random.default_rng(seed)
    matrix = rng.integers(min_val, max_val + 1, size=(rows, cols))
    return pd.DataFrame(matrix)
